type FacultyClass = { id: string; name: string; subject: string; section: string; semester: string; year: string; strength: number; students: string[]; mse1QuestionPaper?: boolean; mse1MarkList?: boolean; mse2QuestionPaper?: boolean; mse2MarkList?: boolean };
const defaultFacultyClasses: FacultyClass[] = [{ id: "class-a", name: "CSE · Semester 5 · Section A", subject: "DBMS", section: "A", semester: "5", year: "2026–2027", strength: 48, students: ["CSE2026A042 · Aarav Sharma", "CSE2026A043 · Priya Nair"] }];
function useFacultyClasses() {
  const [classes, setClasses] = useState<FacultyClass[]>(() => { try { return JSON.parse(localStorage.getItem("learnmesh-faculty-classes") || "null") || defaultFacultyClasses; } catch { return defaultFacultyClasses; } });
  useEffect(() => { localStorage.setItem("learnmesh-faculty-classes", JSON.stringify(classes)); }, [classes]);
  return [classes, setClasses] as const;
}
function classLabel(item: FacultyClass) { return `${item.name} · ${item.strength} students`; }


function StatusPill({ children, warn = false }: { children: React.ReactNode; warn?: boolean }) { return <span className={`status-pill ${warn ? "warn" : ""}`}><span className="dot" />{children}</span>; }
function SelectField({ label, children, value, onChange }: { label: string; children?: React.ReactNode; value?: string; onChange?: (e: React.ChangeEvent<HTMLSelectElement>) => void }) { return <div className="field"><label>{label}</label><select value={value} onChange={onChange}>{children}</select></div>; }
function Metric({ icon: Icon, label, value, footer, tone = "green" }: { icon: typeof Activity; label: string; value: string; footer: React.ReactNode; tone?: string }) { return <div className="metric-card"><div className="metric-top"><span>{label}</span><span className="metric-icon" style={{ color: tone }}><Icon size={14} /></span></div><div className="metric-value">{value}</div><div className="metric-footer">{footer}</div></div>; }
function SectionTitle({ title, note, action }: { title: string; note?: string; action?: string }) { return <div className="card-title-row"><div><div className="card-title">{title}</div>{note && <div className="card-note">{note}</div>}</div>{action && <button className="card-action">{action} <ChevronRight size={12} /></button>}</div>; }
function Evidence({ items }: { items: [string, string][] }) { return <div className="evidence-list">{items.map(([title, detail]) => <div className="evidence-item" key={title}><CheckCircle2 size={13} /><div><strong>{title}</strong><span>{detail}</span></div></div>)}</div>; }

function Sidebar({ role, path, open, onClose }: { role: Role; path: string; open: boolean; onClose: () => void }) {
  const nav = role === "student" ? studentNav : facultyNav;
  return <>
    {open && <div className="sidebar-backdrop" onClick={onClose} />}
    <aside className={`sidebar ${open ? "open" : ""}`}>
      <div className="brand"><div className="brand-mark"><Hexagon size={18} strokeWidth={2.2} /></div><div><div className="brand-name">LearnMesh</div><div className="brand-meta">Academic intelligence</div></div><button onClick={onClose} className="mobile-menu" style={{ marginLeft: "auto", background: "transparent", border: 0, color: "#a6b8ae" }}><X size={17} /></button></div>
      <div className="sidebar-scroll">
        <div className="nav-section">WORKSPACE</div>
        {nav.slice(0, 3).map(([label, href, Icon]) => <Link key={href + label} href={href} className={`nav-item ${path === href ? "active" : ""}`} onClick={onClose}><span className="nav-icon"><Icon size={15} /></span>{label}</Link>)}
        <div className="nav-section">{role === "student" ? "STUDENT PORTAL" : "FACULTY PORTAL"}</div>
        {nav.slice(3).map(([label, href, Icon]) => <Link key={href + label} href={href} className={`nav-item ${path === href ? "active" : ""}`} onClick={onClose}><span className="nav-icon"><Icon size={15} /></span>{label}</Link>)}
        <div className="nav-section">AI AGENT NETWORK</div>
        {(Object.keys(agentMeta) as AgentKey[]).map(key => { const item = agentMeta[key]; const Icon = item.icon; const href = `/agents/${key}`; return <Link key={key} href={href} className={`nav-item ${path === href ? "active" : ""}`} onClick={onClose}><span className="nav-icon" style={{ color: item.color }}><Icon size={15} /></span><span style={{ flex: 1 }}>{item.label}</span><span className={`agent-dot ${item.status === "monitoring" ? "monitoring" : ""}`} /></Link>; })}
      </div>
      <div className="sidebar-bottom"><div className="profile-mini"><div className="avatar">{initials(role)}</div><div style={{ minWidth: 0, flex: 1 }}><strong>{profileName(role)}</strong><span>{contextLabel(role)}</span></div><Settings2 size={14} color="#799087" /></div></div>
    </aside>
  </>;
}

