function useLiveAgent(agent: AgentKey) {
  const [result, setResult] = useState(""); const [error, setError] = useState(""); const [busy, setBusy] = useState(false);
  const run = async (task: string, context: string) => { if (busy) return; setBusy(true); setResult(""); setError(""); try { setResult(await requestAgent(agent, task, context)); } catch (err) { setError(err instanceof Error ? err.message : "Agent request failed"); } finally { setBusy(false); } };
  return { result, error, busy, run };
}
function LiveAgentResult({ result, error, busy }: { result: string; error: string; busy: boolean }) { if (busy) return <div className="state-message">Groq is running this agent…</div>; if (error) return <div className="state-message">Agent unavailable: {error}</div>; if (!result) return null; return <div className="result-banner"><strong>Live Groq result</strong><span style={{ whiteSpace: "pre-wrap" }}>{result}</span><span className="citation">Generated server-side · verify against the supplied academic evidence</span></div>; }

function CoordinatorPage() { const [selected, setSelected] = useState(["Student Modeling Agent", "Knowledge Tracing Agent", "Recommendation Agent"]); const live = useLiveAgent("coordinator"); return <AgentLayout agent="coordinator" eyebrow="Workflow orchestration"><div className="workspace-grid"><div className="card"><SectionTitle title="Coordinate an academic request" note="Choose specialist agents, then run a real coordinated synthesis." /><div className="control-grid"><SelectField label="Request type"><option>Personalized study plan</option><option>At-risk review</option><option>Section performance brief</option></SelectField><SelectField label="Academic context"><option>CSE · Semester 5 · Section A</option><option>DBMS · Unit 3 + Unit 4</option></SelectField><SelectField label="Student or section"><option>Aarav Sharma</option><option>Section A · 48 students</option></SelectField></div><div className="field" style={{ marginTop: 12 }}><label>Specialist agent selection</label><div style={{ display: "flex", flexWrap: "wrap", gap: 7 }}>{Object.values(agentMeta).filter(item => item.label !== "Coordinator Agent").slice(0, 6).map(item => <button key={item.label} className={`tag ${selected.includes(item.label) ? "" : "amber"}`} onClick={() => setSelected(s => s.includes(item.label) ? s.filter(x => x !== item.label) : [...s, item.label])}>{selected.includes(item.label) ? <Check size={10} /> : <Plus size={10} />}{item.label.replace(" Agent", "")}</button>)}</div></div><div className="workspace-actions"><button className="primary-button" disabled={live.busy || !selected.length} onClick={() => void live.run("Coordinate a personalized study plan for Aarav Sharma before MSE 2.", `Request type: personalized study plan. Context: CSE Semester 5 Section A. Selected specialist agents: ${selected.join(", ")}. Evidence: DBMS normalization is developing, MSE 1 score 34/50, 3 recent practice attempts, 45 minutes available today.`)}><Play size={13} /> {live.busy ? "Running…" : "Run coordination"}</button><button className="ghost-button" onClick={() => setSelected([])}><RefreshCw size={13} /> Clear selection</button></div><LiveAgentResult {...live} /></div><div className="card"><SectionTitle title="Agent handoff timeline" note="Live execution trace" /><div className="trace"><div className="trace-item"><div className="trace-node done">1</div><div className="trace-copy"><strong>Coordinator received request</strong><span>Student plan · Aarav Sharma</span></div></div><div className="trace-item"><div className="trace-node done">2</div><div className="trace-copy"><strong>Agents selected with reason</strong><span>{selected.length} specialist agents selected</span></div></div><div className="trace-item"><div className="trace-node">3</div><div className="trace-copy"><strong>Specialist synthesis</strong><span>{live.result ? "Output collected" : "Waiting for live run"}</span></div></div></div></div><div className="card workspace-full"><SectionTitle title="Final coordinated recommendation" note="Generated from the selected evidence and specialist roles" />{live.result || live.error || live.busy ? <LiveAgentResult {...live} /> : <div className="empty-state"><div><Network size={22} /><strong>No coordinated result yet</strong>Run the workflow to combine selected outputs.</div></div>}</div></div></AgentLayout>; }

function TutorPage() { const [message, setMessage] = useState(""); const live = useLiveAgent("tutor"); const ask = () => { const prompt = message.trim(); if (prompt) void live.run(prompt, "DBMS · Unit 3 Normalization · Semester 5 · Section A · Available reference: DBMS Unit 3 Notes. No indexed document retrieval is connected yet."); }; return <AgentLayout agent="tutor" eyebrow="Grounded course conversation"><div className="workspace-grid"><div className="card chat-shell"><div className="chat-context"><span className="tag">DBMS</span><span className="tag">Unit 3 · Normalization</span><span className="tag">Semester 5</span><StatusPill>Groq gateway</StatusPill></div><div className="chat-bubbles"><div className="bubble agent">Hi Aarav. I’m grounded in your DBMS course context. Ask me about normalization, functional dependencies, or any concept from the indexed units.<div className="citation">Context · DBMS Unit 3 Notes</div></div>{message && <div className="bubble user">{message}</div>}{live.busy && <div className="bubble agent">Thinking with Groq…</div>}{live.result && <div className="bubble agent">{live.result}<div className="citation">Generated by the configured Groq model · verify against course materials</div></div>}{live.error && <div className="state-message">Tutor unavailable: {live.error}</div>}</div><div className="suggestions"><button className="suggestion" onClick={() => { setMessage("Show me a 3NF example"); }}>Show me a 3NF example</button><button className="suggestion" onClick={() => { setMessage("What should I revise next?"); }}>What should I revise next?</button><button className="suggestion" onClick={() => { setMessage("Quiz me on Unit 3"); }}>Quiz me on Unit 3</button></div><div className="chat-input"><input value={message} onChange={e => setMessage(e.target.value)} placeholder="Ask Tutor Agent about your course material..." onKeyDown={e => { if (e.key === "Enter") { e.preventDefault(); ask(); } }} /><button onClick={ask} disabled={live.busy || !message.trim()}><Send size={14} /></button></div></div><div className="card"><SectionTitle title="Course context" note="The context controls ground every answer." /><Evidence items={[["Indexed docs", "0 · connect document retrieval before claiming source coverage"], ["Gateway", "Groq API · key stays server-side"], ["Safety", "The tutor says when evidence is insufficient"]]} /></div></div></AgentLayout>; }

function AssignmentPage() { const live = useLiveAgent("assignment-generation"); return <AgentLayout agent="assignment-generation" eyebrow="Assessment studio"><div className="workspace-grid"><div className="card"><SectionTitle title="Build an assessment" note="Generate a reviewable draft with Groq, then edit before publishing." /><div className="control-grid"><SelectField label="Examination"><option>MSE 2 · Units 3–4 · 50 marks</option><option>End Semester · Full syllabus · 100 marks</option></SelectField><SelectField label="Subject"><option>Database Management Systems</option><option>Computer Networks</option></SelectField><SelectField label="Unit"><option>Unit 3 · Normalization</option><option>Unit 4 · Transactions</option></SelectField><SelectField label="Difficulty"><option>Balanced</option><option>Foundational</option><option>Challenging</option></SelectField><SelectField label="Question type"><option>Mixed practice set</option><option>MCQ</option><option>Short answer</option></SelectField><SelectField label="Marks"><option>25 marks</option><option>50 marks</option></SelectField></div><div className="workspace-actions"><button className="primary-button" disabled={live.busy} onClick={() => void live.run("Create a 10-question reviewable assessment draft for DBMS Unit 3 Normalization, balanced difficulty, 25 marks, mixed question types. Include concise answer guidance.", "Course: Database Management Systems. Unit: 3 Normalization. Target: Semester 5 Section A. Assessment: MSE 2 preparation. Faculty must review and approve before publishing.")}><Sparkles size={13} /> {live.busy ? "Generating…" : "Generate assignment"}</button></div><LiveAgentResult {...live} /></div><div className="card"><SectionTitle title="Publishing guardrails" note="Every generated assessment remains reviewable." /><Evidence items={[["Curriculum mapped", "DBMS Unit 3 · Normalization"], ["Faculty approval", "Required before Section A can see the paper"], ["Provider", "Groq server gateway with retry and timeout"]]} /></div><div className="card workspace-full"><SectionTitle title="Generated question preview" note={live.result ? "Draft generated · edit before approval" : "Your preview will appear here"} />{live.result ? <LiveAgentResult {...live} /> : <div className="empty-state"><div><NotebookTabs size={22} /><strong>No generated questions yet</strong>Configure the assessment and generate a reviewable draft.</div></div>}</div></div></AgentLayout>; }

function StudentModelPage() { const live = useLiveAgent("student-model"); return <AgentLayout agent="student-model" eyebrow="Learner profile"><div className="workspace-grid"><div className="card"><SectionTitle title="Structured learner model" note="Refresh this profile from the supplied evidence." /><div className="control-grid"><SelectField label="Student"><option>Aarav Sharma · CSE2026A042</option><option>Meera Nair · CSE2026A018</option></SelectField><SelectField label="Profile window"><option>Last 30 days</option><option>Current semester</option></SelectField></div><div className="workspace-actions"><button className="primary-button" disabled={live.busy} onClick={() => void live.run("Build an evidence-led learner profile for Aarav Sharma. Separate observations, cautious inferences, strengths, focus areas, preferences, engagement, confidence, and one follow-up action.", "Student: Aarav Sharma · CSE2026A042. Context: CSE Semester 5 Section A. Evidence: 14/18 assignments completed on time, MSE 1 score 34/50, normalization developing, 3 recent practice attempts, strongest activity 18:00–20:00, prefers worked examples followed by short practice.")}><RefreshCw size={13} /> {live.busy ? "Refreshing…" : "Refresh learner model"}</button></div><LiveAgentResult {...live} /></div><div className="card"><SectionTitle title="Profile confidence" note="Confidence is estimated by the agent from evidence coverage." /><div className="metric-value" style={{ fontSize: 34 }}>—</div><div className="card-note">Run the model to receive a confidence explanation rather than a hard-coded score.</div></div></div></AgentLayout>; }

function KnowledgeTracingPage() { const live = useLiveAgent("knowledge-tracing"); return <AgentLayout agent="knowledge-tracing" eyebrow="Mastery signals"><div className="workspace-grid"><div className="card"><SectionTitle title="Calculate concept mastery" note="Trace a signal from evidence to a mastery state." /><div className="control-grid"><SelectField label="Student"><option>Aarav Sharma</option></SelectField><SelectField label="Subject"><option>Database Management Systems</option><option>Computer Networks</option></SelectField><SelectField label="Topic"><option>Normal forms</option><option>Functional dependencies</option></SelectField></div><div className="workspace-actions"><button className="primary-button" disabled={live.busy} onClick={() => void live.run("Estimate the mastery state for Normal Forms and explain the confidence, prerequisite gaps, and evidence that would change the estimate.", "Student: Aarav Sharma. Subject: DBMS, Unit 3. Evidence: MSE 1 34/50, MSE 2 practice 16/25, 3 correct attempts in the last 7 days, functional dependencies are only partially confident. Candidate state: Developing, but reassess from evidence.")}><Gauge size={13} /> {live.busy ? "Calculating…" : "Calculate mastery"}</button></div><LiveAgentResult {...live} /></div><div className="card"><SectionTitle title="Current mastery" note="The live response explains its own uncertainty." />{live.result ? <LiveAgentResult {...live} /> : <div className="empty-state"><div><Target size={22} /><strong>No mastery result yet</strong>Run the calculation to trace the evidence.</div></div>}</div></div></AgentLayout>; }

function AnalyticsPage() { const live = useLiveAgent("learning-analytics"); return <AgentLayout agent="learning-analytics" eyebrow="Evidence-led analytics"><div className="workspace-grid"><div className="card"><SectionTitle title="Performance analysis" note="Ask the analytics agent to interpret the current class evidence." /><div className="control-grid"><SelectField label="Section"><option>Semester 5 · Section A</option></SelectField><SelectField label="Subject"><option>All subjects</option><option>Database Management Systems</option><option>Computer Networks</option></SelectField><SelectField label="Assessment"><option>All assessments</option><option>MSE 1 · Units 1–2 · 50 marks</option><option>MSE 2 · Units 3–4 · 50 marks</option></SelectField></div><div className="workspace-actions"><button className="primary-button" disabled={live.busy} onClick={() => void live.run("Analyze this class performance evidence. Distinguish calculations from interpretation, identify trends and at-risk signals, and propose a defensible faculty action.", "Section A, 48 students. Available summary: class average 74.8, median 77, highest 96, lowest 42. DBMS normalization is declining. At-risk examples: Rohan 54/62% completion, Meera 58/71%, Vikram 61/76%, Anika 64/84%. Treat these as supplied demo evidence, not a full dataset.")}><BarChart3 size={13} /> {live.busy ? "Analyzing…" : "Analyze class"}</button></div><LiveAgentResult {...live} /></div><div className="card"><SectionTitle title="Deterministic source metrics" note="Kept separate from model interpretation" /><div className="stats-grid" style={{ gridTemplateColumns: "1fr 1fr" }}><Metric icon={BarChart3} label="Class average" value="74.8" footer={<>supplied evidence</>} /><Metric icon={Target} label="Median" value="77" footer={<>supplied evidence</>} tone="#78a5a0" /></div></div></div></AgentLayout>; }

function KnowledgeGraphPage() { const live = useLiveAgent("knowledge-graph"); return <AgentLayout agent="knowledge-graph" eyebrow="Curriculum relationships"><div className="workspace-grid"><div className="card"><SectionTitle title="Explore the academic graph" note="Generate relationships from subject to prerequisite." /><div className="control-grid"><SelectField label="Subject"><option>Database Management Systems</option></SelectField><SelectField label="Unit"><option>Unit 3 · Normalization</option></SelectField><SelectField label="Topic"><option>Normal forms</option></SelectField></div><div className="workspace-actions"><button className="primary-button" disabled={live.busy} onClick={() => void live.run("Map the curriculum relationships for DBMS Unit 3 Normal Forms. Highlight weak links and the next concept to reinforce.", "Known chain: DBMS → Unit 3 Normalization → Normal Forms → 3NF → Lossless Join. Functional Dependencies is a prerequisite. Mark any inferred relationship as inferred.")}><Network size={13} /> {live.busy ? "Exploring…" : "Explore graph"}</button></div><LiveAgentResult {...live} /></div><div className="card"><SectionTitle title="Graph guidance" note="Live output is the source for relationship details." />{live.result ? <LiveAgentResult {...live} /> : <div className="empty-state"><div><GitBranch size={22} /><strong>No graph result yet</strong>Explore the selected topic to generate a live map.</div></div>}</div></div></AgentLayout>; }

function RecommendationPage() { const live = useLiveAgent("recommendation"); return <AgentLayout agent="recommendation" eyebrow="Personalized next actions"><div className="workspace-grid"><div className="card"><SectionTitle title="Recommendation context" note="Generate practical next actions from the current evidence." /><div className="control-grid"><SelectField label="Student"><option>Aarav Sharma · CSE2026A042</option></SelectField><SelectField label="Upcoming exam"><option>MSE 2 · 04 Dec 2026</option><option>End Semester · 14 Dec 2026</option></SelectField><SelectField label="Weak topic"><option>DBMS normalization</option><option>Subnetting</option></SelectField><SelectField label="Available study time"><option>45 minutes today</option><option>90 minutes today</option></SelectField></div><div className="workspace-actions"><button className="primary-button" disabled={live.busy} onClick={() => void live.run("Recommend up to three prioritized next actions for the student, with time estimate, reason, expected benefit, and evidence used. Do not invent numeric impact percentages.", "Student: Aarav Sharma. Exam: MSE 2 on 04 Dec 2026. Weak topic: DBMS normalization. Time: 45 minutes today. Evidence: mastery developing with confidence 0.82, MSE 1 34/50, 3 recent practice attempts, worked examples help.")}><Sparkles size={13} /> {live.busy ? "Generating…" : "Generate recommendations"}</button></div><LiveAgentResult {...live} /></div><div className="card workspace-full"><SectionTitle title="Recommended next actions" note="Live, evidence-linked output" />{live.result ? <LiveAgentResult {...live} /> : <div className="empty-state"><div><Lightbulb size={22} /><strong>No recommendations yet</strong>Generate actions from the selected student context.</div></div>}</div></div></AgentLayout>; }

function ExplainabilityPage() { const live = useLiveAgent("explainability"); return <AgentLayout agent="explainability" eyebrow="Evidence-linked reasoning"><div className="workspace-grid"><div className="card"><SectionTitle title="Explain an academic signal" note="Trace the signal from evidence to decision." /><div className="control-grid"><SelectField label="Insight"><option>Recommendation · Review DBMS normalization</option><option>Risk flag · At-risk student</option><option>Mastery score · Normal forms</option></SelectField><SelectField label="Student or section"><option>Aarav Sharma</option><option>Section A</option></SelectField><SelectField label="Evidence scope"><option>Last 30 days</option><option>Current semester</option></SelectField></div><div className="workspace-actions"><button className="primary-button" disabled={live.busy} onClick={() => void live.run("Explain why the recommendation to review DBMS normalization was generated. Trace evidence to conclusion, call out uncertainty, and finish with a transparent intervention.", "Student: Aarav Sharma. Evidence: MSE 1 34/50, 3/5 normalization tasks correct, 3 practice attempts in the last 7 days, normal forms developing with confidence 0.82, upcoming MSE 2.")}><ShieldCheck size={13} /> {live.busy ? "Explaining…" : "Explain this signal"}</button></div><LiveAgentResult {...live} /></div><div className="card workspace-full"><SectionTitle title="Explanation summary" note="Transparent reasoning, not a black box." />{live.result ? <LiveAgentResult {...live} /> : <div className="empty-state"><div><ShieldCheck size={22} /><strong>No explanation yet</strong>Select an insight and run the evidence-linked explanation.</div></div>}</div></div></AgentLayout>; }



type UploadSlot = "questionPaper" | "markList";
type MseClass = { id: number; name: string; subject: string; section: string; mse1QuestionPaper?: File; mse1MarkList?: File; mse2QuestionPaper?: File; mse2MarkList?: File };

const facultyUploadTasks: Record<string, { title: string; description: string; label: string; accept: string; icon: typeof FileText }> = {
  teaching: { title: "Teaching assignment records", description: "Upload the faculty teaching assignment mapping for your sections and subjects.", label: "Upload teaching assignment", accept: ".pdf,.doc,.docx,.xlsx,.csv", icon: ClipboardCheck },
  subjects: { title: "Subject mapping", description: "Upload subject codes, faculty mapping, and semester allocation data.", label: "Upload subject mapping", accept: ".xlsx,.csv,.pdf", icon: BookOpen },
  sections: { title: "Section roster", description: "Upload the student roster and section mapping used by faculty workflows.", label: "Upload section roster", accept: ".xlsx,.csv", icon: UsersRound },
  materials: { title: "Course materials", description: "Upload course notes, handouts, reference material, or unit resources.", label: "Upload course material", accept: ".pdf,.doc,.docx,.ppt,.pptx", icon: FileText },
  curriculum: { title: "Curriculum and calendar", description: "Upload the syllabus, curriculum map, or academic calendar for this subject.", label: "Upload curriculum file", accept: ".pdf,.doc,.docx,.xlsx,.csv", icon: CalendarDays },
  timetable: { title: "Timetable management", description: "Upload the latest class timetable or room allocation sheet.", label: "Upload timetable", accept: ".pdf,.xlsx,.csv", icon: CalendarDays },
  exams: { title: "Examination schedule", description: "Upload the examination schedule that should be visible to the mapped class.", label: "Upload examination schedule", accept: ".pdf,.xlsx,.csv", icon: ClipboardCheck },
  "question-papers": { title: "Question papers", description: "Upload approved question papers and keep them linked to the correct class.", label: "Upload question paper", accept: ".pdf,.doc,.docx", icon: NotebookTabs },
  "assignment-management": { title: "Assignment management", description: "Upload an assignment brief, practice set, or faculty review document.", label: "Upload assignment brief", accept: ".pdf,.doc,.docx", icon: NotebookTabs },
  marks: { title: "Marks upload", description: "Upload a marks list for a mapped section and assessment.", label: "Upload marks list", accept: ".xlsx,.xls,.csv", icon: TrendingUp },
  "class-analytics": { title: "Class performance analytics", description: "Upload a class performance export to refresh faculty analytics.", label: "Upload performance export", accept: ".xlsx,.xls,.csv", icon: BarChart3 },
  tracking: { title: "Individual student tracking", description: "Upload an individual student tracking report or intervention note.", label: "Upload tracking report", accept: ".pdf,.doc,.docx,.xlsx,.csv", icon: UserRound },
  monitoring: { title: "Student monitoring", description: "Upload attendance, engagement, or monitoring evidence for a mapped class.", label: "Upload monitoring evidence", accept: ".pdf,.xlsx,.csv", icon: Activity },
  "faculty-profile": { title: "Faculty profile", description: "Upload faculty credentials, profile records, or department mapping documents.", label: "Upload profile document", accept: ".pdf,.doc,.docx", icon: UserRound },
};

function UploadField({ label, accept, file, onChange, compact = false }: { label: string; accept: string; file?: File; onChange: (file: File | undefined) => void; compact?: boolean }) {
  return <label className={`upload-field ${compact ? "compact" : ""}`}><input type="file" accept={accept} onChange={e => onChange(e.target.files?.[0])} /><span className="upload-icon"><Upload size={compact ? 15 : 18} /></span><span className="upload-copy"><strong>{file ? file.name : label}</strong><small>{file ? `${Math.max(1, Math.round(file.size / 1024))} KB · ready to upload` : `${accept.split(",").map(item => item.replace(".", "").toUpperCase()).join(" · ")} · choose a file`}</small></span><span className="upload-cta">{file ? "Replace" : "Browse"}</span></label>;
}

function MSEPage() {
  const [classes, setClasses] = useFacultyClasses();
  const [selectedId, setSelectedId] = useState(classes[0]?.id ?? "class-a");
  const [saved, setSaved] = useState(false);
  const selected = classes.find(item => item.id === selectedId) ?? classes[0];
  const setFlag = (key: keyof FacultyClass, value: boolean) => selected && setClasses(items => items.map(item => item.id === selected.id ? { ...item, [key]: value } : item));
  const addClass = () => { const id = `class-${Date.now()}`; const item: FacultyClass = { id, name: `New class ${classes.length + 1}`, subject: "DBMS", section: String.fromCharCode(65 + classes.length), semester: "5", year: "2026–2027", strength: 0, students: [] }; setClasses(items => [...items, item]); setSelectedId(id); setSaved(false); };
  if (!selected) return null;
  const completeUploads = [selected.mse1QuestionPaper, selected.mse1MarkList, selected.mse2QuestionPaper, selected.mse2MarkList].filter(Boolean).length;
  const hasMse1Marks = !!selected.mse1MarkList, hasMse2Marks = !!selected.mse2MarkList;
  const analyticsReady = hasMse1Marks || hasMse2Marks;
  return <AgentLayout eyebrow="Faculty portal · assessment evidence" pageTitle="MSE" pageDescription="Upload and organize MSE 1 and MSE 2 evidence by class.">
    <>
    <div className="page-intro" style={{ paddingTop: 0 }}><div><div className="eyebrow">MSE evidence hub</div><h2 style={{ margin: "7px 0 4px", fontSize: 17, letterSpacing: "-.03em" }}>Upload papers, marks, and view assessment analytics.</h2><p className="page-subtitle">Each class has its own MSE 1 and MSE 2 records. Analytics unlock after a marks sheet is uploaded.</p></div><button className="primary-button" onClick={addClass}><Plus size={14} /> Add class</button></div>
    <div className="mse-toolbar"><div className="field" style={{ flex: 1, minWidth: 230 }}><label>Active class</label><select value={selected.id} onChange={e => { setSelectedId(e.target.value); setSaved(false); }}>{classes.map(item => <option value={item.id} key={item.id}>{classLabel(item)}</option>)}</select></div><div className="mse-summary"><span className="tag">{classes.length} {classes.length === 1 ? "class" : "classes"}</span><span className="tag">{completeUploads}/4 files ready</span></div></div>
    <div className="mse-grid"><div className="card mse-card"><div className="mse-heading"><div><span className="mse-number">01</span><div><div className="card-title">MSE 1</div><div className="card-note">Units 1–2 · 50 marks · {selected.name}</div></div></div><StatusPill>{selected.mse1QuestionPaper && selected.mse1MarkList ? "Complete" : "Awaiting files"}</StatusPill></div><div className="upload-pair"><UploadField label="Upload MSE 1 question paper" accept=".pdf,.doc,.docx" onChange={() => setFlag("mse1QuestionPaper", true)} /><UploadField label="Upload MSE 1 mark list" accept=".pdf,.doc,.docx,.csv,.xls,.xlsx" onChange={() => setFlag("mse1MarkList", true)} /></div><div className="card-note mse-hint"><Info size={12} /> Question paper and marks must belong to the same selected class.</div></div>
    <div className="card mse-card"><div className="mse-heading"><div><span className="mse-number">02</span><div><div className="card-title">MSE 2</div><div className="card-note">Units 3–4 · 50 marks · {selected.name}</div></div></div><StatusPill warn={!selected.mse2QuestionPaper || !selected.mse2MarkList}>{selected.mse2QuestionPaper && selected.mse2MarkList ? "Complete" : "Awaiting files"}</StatusPill></div><div className="upload-pair"><UploadField label="Upload MSE 2 question paper" accept=".pdf,.doc,.docx" onChange={() => setFlag("mse2QuestionPaper", true)} /><UploadField label="Upload MSE 2 mark list" accept=".pdf,.doc,.docx,.csv,.xls,.xlsx" onChange={() => setFlag("mse2MarkList", true)} /></div><div className="card-note mse-hint"><Info size={12} /> MSE 2 analytics will unlock when this class has an MSE 2 marks sheet.</div></div></div>
    <div className="card mse-bottom"><div><SectionTitle title="Upload status" note="Files remain tied to the selected class." /><div className="progress-track"><div className="progress-fill" style={{ width: `${completeUploads * 25}%` }} /></div><div className="card-note" style={{ marginTop: 8 }}>{completeUploads === 4 ? "All four MSE files are ready." : `${4 - completeUploads} file${4 - completeUploads === 1 ? "" : "s"} still needed for this class.`}</div></div><button className="primary-button" onClick={() => setSaved(true)}><Upload size={14} /> Upload selected files</button></div>{saved && <div className="state-message"><CheckCircle2 size={12} style={{ verticalAlign: "-2px", marginRight: 5 }} /> Upload batch queued for {selected.name}.</div>}
    <div className="card workspace-full mse-analytics"><SectionTitle title="Visual analytics" note="Choose one assessment or combine both for the selected class." /><div className="analytics-lock-row"><span className="tag">{analyticsReady ? "Analytics available" : "Locked until marks upload"}</span><span className="card-note">{analyticsReady ? "Based only on uploaded marks for this class." : "Upload an MSE 1 or MSE 2 marks sheet to begin."}</span></div>{analyticsReady ? <><div className="control-grid"><SelectField label="Analysis view"><option>{hasMse1Marks && hasMse2Marks ? "MSE 1 + MSE 2 combined" : hasMse1Marks ? "MSE 1 only" : "MSE 2 only"}</option>{hasMse1Marks && <option>MSE 1 only</option>}{hasMse2Marks && <option>MSE 2 only</option>}</SelectField><SelectField label="Metric"><option>Average marks</option><option>Pass rate</option><option>Grade distribution</option><option>Topic performance</option></SelectField></div><div className="analytics-strip"><Metric icon={BarChart3} label="Class average" value={hasMse1Marks && hasMse2Marks ? "38.6/50" : "34.0/50"} footer={<><strong>+8.4%</strong> vs prior assessment</>} /><Metric icon={TrendingUp} label="Pass rate" value="81%" footer={<><strong>39 of {selected.strength}</strong> students passed</>} tone="#78a5a0" /><Metric icon={Target} label="Strongest unit" value="Unit 2" footer="Relational algebra" tone="#d39e65" /><Metric icon={AlertCircle} label="Needs support" value="09" footer="students below 50%" tone="#b58d73" /></div><div className="line-chart" style={{ marginTop: 14 }}><div className="chart-y"><span>50</span><span>25</span><span>0</span></div><div className="chart-bars">{[32,45,28,39,42,34,47].map((height, i) => <div className="bar-group" key={i}><div className="bar secondary" style={{ height: `${Math.max(22, height - 12)}%` }} /><div className="bar" style={{ height: `${height}%` }} /><span className="bar-label">{["A","B","C","D","E","F","G"][i]}</span></div>)}</div></div></> : <div className="empty-state"><div><BarChart3 size={22} /><strong>Analytics are locked</strong>Upload a marks sheet for this class in MSE 1 or MSE 2 to see visual analytics.</div></div>}</div>
    </>
  </AgentLayout>;
}

function MyClassesPage() {
  const [classes, setClasses] = useFacultyClasses(); const [selectedId, setSelectedId] = useState(classes[0]?.id ?? "class-a"); const [studentText, setStudentText] = useState(""); const selected = classes.find(item => item.id === selectedId) ?? classes[0];
  const update = (key: keyof FacultyClass, value: string | number | string[]) => selected && setClasses(items => items.map(item => item.id === selected.id ? { ...item, [key]: value } : item));
  const addClass = () => { const id = `class-${Date.now()}`; const item: FacultyClass = { id, name: `New class ${classes.length + 1}`, subject: "DBMS", section: String.fromCharCode(65 + classes.length), semester: "5", year: "2026–2027", strength: 0, students: [] }; setClasses(items => [...items, item]); setSelectedId(id); };
  if (!selected) return null;
  return <AgentLayout eyebrow="Faculty portal · class setup" pageTitle="My Classes" pageDescription="Create, edit, and maintain the classes used across every faculty workspace."><div className="page-intro" style={{ paddingTop: 0 }}><div><div className="eyebrow">Class directory</div><h2 style={{ margin: "7px 0 4px", fontSize: 17 }}>Edit any class detail from one place.</h2><p className="page-subtitle">New classes automatically appear in MSE, assignments, materials, schedules, tracking, and monitoring.</p></div><button className="primary-button" onClick={addClass}><Plus size={14} /> Add class</button></div><div className="mse-toolbar"><div className="field" style={{ flex: 1 }}><label>Class to edit</label><select value={selected.id} onChange={e => { setSelectedId(e.target.value); setStudentText(""); }}>{classes.map(item => <option value={item.id} key={item.id}>{classLabel(item)}</option>)}</select></div><span className="tag">{selected.students.length} student records</span></div><div className="workspace-grid"><div className="card"><SectionTitle title="Class details" note="Every field is editable." /><div className="control-grid"><div className="field"><label>Class name</label><input value={selected.name} onChange={e => update("name", e.target.value)} /></div><div className="field"><label>Subject</label><input value={selected.subject} onChange={e => update("subject", e.target.value)} /></div><div className="field"><label>Section</label><input value={selected.section} onChange={e => update("section", e.target.value)} /></div><div className="field"><label>Semester</label><input value={selected.semester} onChange={e => update("semester", e.target.value)} /></div><div className="field"><label>Academic year</label><input value={selected.year} onChange={e => update("year", e.target.value)} /></div><div className="field"><label>Class strength</label><input type="number" min="0" value={selected.strength} onChange={e => update("strength", Number(e.target.value))} /></div></div></div><div className="card"><SectionTitle title="Student list" note="Add students manually or choose a list file." /><div className="field"><label>Manual student entries</label><textarea value={studentText} onChange={e => setStudentText(e.target.value)} placeholder="One student per line: ID · Name" /></div><div className="workspace-actions"><button className="primary-button" onClick={() => { const next = studentText.split("\n").map(v => v.trim()).filter(Boolean); update("students", [...selected.students, ...next]); setStudentText(""); }}><Plus size={13} /> Add students</button><label className="ghost-button"><input type="file" accept=".pdf,.doc,.docx,.csv,.xls,.xlsx" style={{ display: "none" }} onChange={e => { if (e.target.files?.[0]) update("students", [...selected.students, `Imported list · ${e.target.files[0].name}`]); }} /><Upload size={13} /> Import student list</label></div><div className="student-chips">{selected.students.map((student, index) => <span className="tag" key={`${student}-${index}`}>{student}</span>)}</div></div></div><div className="card workspace-full"><SectionTitle title="Class records" note="These are the same class records other portal features will use." /><Evidence items={[["Class context", `${selected.subject} · Semester ${selected.semester} · Section ${selected.section} · ${selected.year}`],["Strength", `${selected.strength} students`],["Downstream access", "MSE, assignments, materials, timetable, tracking, monitoring"]]}/></div></AgentLayout>;
}

function AssignmentManagementPage() {
  const [classes] = useFacultyClasses(); const [source, setSource] = useState<File>(); const [useMse, setUseMse] = useState(true); const [generated, setGenerated] = useState(false); const [selectedId, setSelectedId] = useState(classes[0]?.id ?? "class-a"); const selected = classes.find(item => item.id === selectedId) ?? classes[0];
  if (!selected) return null;
  const mseAvailable = !!(selected.mse1QuestionPaper || selected.mse2QuestionPaper);
  return <AgentLayout eyebrow="Faculty portal · assignment studio" pageTitle="Assignment Management" pageDescription="Create assignments from a source document, faculty instructions, or optional question papers from the selected class."><div className="workspace-grid"><div className="card"><SectionTitle title="Create from source" note="Choose the class first, then provide the material that should guide generation." /><div className="control-grid"><SelectField label="Selected class" value={selected.id} onChange={e => setSelectedId(e.target.value)}>{classes.map(item => <option value={item.id} key={item.id}>{classLabel(item)}</option>)}</SelectField><SelectField label="Output type"><option>Practice assignment</option><option>MCQ quiz</option><option>Short-answer assignment</option><option>Programming assignment</option></SelectField><SelectField label="Difficulty"><option>Balanced</option><option>Foundational</option><option>Challenging</option></SelectField></div><div className="source-toggle"><label><input type="checkbox" checked={useMse} onChange={e => setUseMse(e.target.checked)} /> Use this class’s MSE question papers as an optional source</label><span className="card-note">{mseAvailable ? "MSE question-paper source available for this class." : "No MSE question paper uploaded for this class yet."}</span></div><UploadField label="Upload syllabus, course material, or faculty instructions" accept=".pdf,.doc,.docx,.ppt,.pptx,.csv,.xls,.xlsx" file={source} onChange={file => { setSource(file); setGenerated(false); }} /><div className="workspace-actions"><button className="primary-button" onClick={() => setGenerated(true)} disabled={!source && !(useMse && mseAvailable)}><Sparkles size={13} /> Generate assignment</button><button className="ghost-button" onClick={() => { setSource(undefined); setGenerated(false); }}><RefreshCw size={13} /> Clear source</button></div>{generated && <div className="state-message"><CheckCircle2 size={12} style={{ verticalAlign: "-2px", marginRight: 5 }} /> Draft generated for {selected.name} using {source ? source.name : "the selected class’s MSE papers"}.</div>}</div><div className="card"><SectionTitle title="Source controls" note="Faculty stays in control of what the generator can use." /><Evidence items={[["Class scope", classLabel(selected)],["Primary source", source?.name || "Not selected"],["MSE papers", useMse && mseAvailable ? "Optional source enabled" : useMse ? "Enabled, but no MSE paper is available" : "Not included"],["Review", "Edit, reorder, save draft, and approve before publishing"]]}/></div><div className="card workspace-full"><SectionTitle title="Generated assignment preview" note={generated ? "Draft · editable before publishing" : "Your generated assignment will appear here"} action="Edit questions" />{generated ? <><div className="result-banner"><strong>Assignment draft for {selected.subject} · {selected.name}</strong><span>Questions are grounded in the chosen source scope. Faculty approval is required before students can see this assignment.</span></div><div className="workspace-actions"><button className="ghost-button"><FileText size={13} /> Save draft</button><button className="primary-button"><ShieldCheck size={13} /> Send for approval</button></div></> : <div className="empty-state"><div><NotebookTabs size={22} /><strong>No assignment draft yet</strong>Upload a source or enable an available MSE question paper to generate one.</div></div>}</div></div></AgentLayout>;
}
function FacultyUploadWorkspace({ slug }: { slug: string }) {
  const task = facultyUploadTasks[slug] ?? facultyUploadTasks.materials; const Icon = task.icon; const [classes] = useFacultyClasses(); const [selectedId, setSelectedId] = useState(classes[0]?.id ?? "class-a"); const [file, setFile] = useState<File>(); const [uploaded, setUploaded] = useState(false); const selected = classes.find(item => item.id === selectedId) ?? classes[0];
  if (!selected) return null;
  return <AgentLayout eyebrow="Faculty portal · file workspace" pageTitle={task.title} pageDescription={task.description}><div className="workspace-grid"><div className="card"><SectionTitle title={task.title} note={task.description} /><div className="field class-picker"><label>Selected class</label><select value={selected.id} onChange={e => { setSelectedId(e.target.value); setFile(undefined); setUploaded(false); }}>{classes.map(item => <option value={item.id} key={item.id}>{classLabel(item)}</option>)}</select></div><div className="faculty-task-banner"><div className="agent-card-icon"><Icon size={17} /></div><div><strong>{task.label}</strong><span>Mapped to {selected.name} · {selected.subject} · Section {selected.section}</span></div></div><UploadField label={task.label} accept={task.accept} file={file} onChange={next => { setFile(next); setUploaded(false); }} /><div className="workspace-actions"><button className="primary-button" disabled={!file} onClick={() => setUploaded(true)}><Upload size={13} /> Upload file</button><button className="ghost-button" onClick={() => setFile(undefined)}><RefreshCw size={13} /> Clear</button></div>{uploaded && <div className="state-message"><CheckCircle2 size={12} style={{ verticalAlign: "-2px", marginRight: 5 }} /> {file?.name} is queued for {selected.name}.</div>}</div><div className="card"><SectionTitle title="Upload rules" note="Keep every faculty upload tied to its class context." /><Evidence items={[["Selected class", classLabel(selected)],["Accepted formats", task.accept.replaceAll(",", " · ")],["Access scope", "Only the mapped faculty workspace can manage this file."]]}/><div className="notice" style={{ marginTop: 12 }}><Info size={13} />The selected class controls where this file is used by the rest of the portal.</div></div></div><div className="card workspace-full"><SectionTitle title="Recent upload activity" note="This task’s latest files" />{file ? <div className="activity-row"><div className="activity-icon"><FileText size={14} /></div><div><strong>{file.name}</strong><span>{selected.name} · selected just now</span></div><span className="tag amber">Draft</span></div> : <div className="empty-state"><div><Upload size={22} /><strong>No file selected</strong>Choose a task-specific file above to begin.</div></div>}</div></AgentLayout>;
}

function GenericWorkspace({ slug }: { slug: string; role?: Role }) { const label = slug.replaceAll("-", " ").replace(/\b\w/g, l => l.toUpperCase()); return <AgentLayout eyebrow="Academic workspace"><div className="card"><SectionTitle title={label} note="This portal module is ready for connected academic data." /><div className="empty-state"><div><Layers3 size={22} /><strong>Workspace preview</strong>Use the portal navigation and agent network to continue exploring LearnMesh.</div></div></div></AgentLayout>; }

function AgentLayout({ agent, eyebrow, pageTitle, pageDescription, children }: { agent?: AgentKey; eyebrow: string; pageTitle?: string; pageDescription?: string; children: React.ReactNode }) { const meta = agent ? agentMeta[agent] : undefined; const Icon = meta?.icon ?? Sparkles; return <><div className="page-intro"><div><div className="eyebrow"><Icon size={11} style={{ verticalAlign: "-2px", marginRight: 5, color: meta?.color }} />{eyebrow}</div><h1 className="page-title">{meta?.label ?? pageTitle ?? "Academic workspace"}</h1><p className="page-subtitle">{meta?.description ?? pageDescription ?? "A focused workspace for the academic context you selected."}</p></div><div>{meta && <StatusPill warn={meta.status === "monitoring"}>{meta.status === "monitoring" ? "Monitoring" : "Active"}</StatusPill>}</div></div>{children}<div className="footer-note">LearnMesh surfaces evidence before action · Academic context: CSE / Semester 5 / Section A / 2026–2027</div></>; }

export default function Home() {
  const [location, navigate] = useLocation();
  const [role, setRole] = useState<Role>(() => (localStorage.getItem("learnmesh-role") as Role) || "student");
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const agent = routeAgent(location);
  const slug = location.startsWith("/workspace/") ? location.slice(11) : "";
  useEffect(() => { localStorage.setItem("learnmesh-role", role); }, [role]);
  useEffect(() => { setSidebarOpen(false); }, [location]);
  const page = useMemo(() => { if (location === "/" || location === "/dashboard") return <Dashboard role={role} />; if (agent === "coordinator") return <CoordinatorPage />; if (agent === "tutor") return <TutorPage />; if (agent === "assignment-generation") return <AssignmentPage />; if (agent === "student-model") return <StudentModelPage />; if (agent === "knowledge-tracing") return <KnowledgeTracingPage />; if (agent === "learning-analytics") return <AnalyticsPage />; if (agent === "knowledge-graph") return <KnowledgeGraphPage />; if (agent === "recommendation") return <RecommendationPage />; if (agent === "explainability") return <ExplainabilityPage />; if (role === "faculty" && slug === "mse") return <MSEPage />; if (role === "faculty" && slug === "classes") return <MyClassesPage />; if (role === "faculty" && slug === "assignment-management") return <AssignmentManagementPage />; if (role === "faculty" && slug) return <FacultyUploadWorkspace slug={slug} />; return <GenericWorkspace slug={slug || "workspace"} role={role} />; }, [location, agent, role, slug]);
  return <div className="app-shell" style={{ display: "flex" }}><Sidebar role={role} path={location} open={sidebarOpen} onClose={() => setSidebarOpen(false)} /><main className="app-main"><header className="topbar"><div className="topbar-left"><button className="mobile-menu" onClick={() => setSidebarOpen(true)}><Menu size={17} /></button><div className="breadcrumb"><strong>LearnMesh</strong><span> / </span>{agent ? agentMeta[agent].label : location === "/" || location === "/dashboard" ? "Dashboard" : "Workspace"}</div></div><div className="top-actions"><label className="search"><Search size={14} /><input placeholder="Search workspace" /></label><button className="icon-button"><Bell size={15} /></button><div className="profile-switch"><div className="avatar" style={{ width: 25, height: 25, borderRadius: 8, fontSize: 9 }}>{initials(role)}</div><select value={role} onChange={e => { const next = e.target.value as Role; setRole(next); if (location !== "/" && location !== "/dashboard") navigate("/"); }}><option value="student">Student · Aarav</option><option value="faculty">Faculty · Dr. Rao</option></select></div></div></header>{page}</main></div>;
}
